            if u != v and v not in G[u]:
                G[u].append(v)
                G[v].append(u)
                edges_added += 1
        return G

    def bfs_cycle_detection(G):
        n = len(G)
        rank = 0
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                queue = [i]
                parent = [-1] * n
                visited[i] = True
                while queue:
                    u = queue.pop(0)
                    for v in G[u]:
