                            visited[v] = True
                            parent[v] = u
                            queue.append(v)
                        elif parent[u] != v and parent[v] != u:
                            rank += 1
                            break
                else:
                    continue
                break
        return rank

    def k_clique_communication_complexity(n, r):
        if r <= n ** 0.5:
            return n ** 0.5
        else:
            return n ** (1 - r / n)

    n = random.randint(5, 40)
